  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Currently, an adult who may lawfully possess a handgun can carry it concealed without a permit. The measure changes this by establishing a mandatory permit requirement overseen by county sheriffs.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q2",
      "answer": "Applicants will face direct costs and opportunity costs (time) to complete the required eight-hour safety course. Sheriffs' departments will incur administrative costs to process applications and issue permits.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q3",
      "answer": "Handgun owners bear the costs in time and potential fees to meet the new permit and training requirements. Instructors who provide safety courses will likely see increased demand and financial benefit.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Some handgun owners may choose not to carry concealed rather than complete the mandatory process, or they may shift to carrying openly if that remains unrestricted. Demand for certified safety training will rise.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q5",
      "answer": "The measure addresses the perceived risk of untrained individuals carrying concealed firearms in public spaces. The mechanism targets this by mandating safety training and verification by a sheriff before a permit is granted.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q6",
      "answer": "County sheriffs gain an administrative role in processing permits, though it is a 'shall issue' duty rather than fully discretionary. Firearms safety instructors gain a captive market of mandated customers.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "Researchers disagree about the effects of concealed carry permitting regimes on public safety. Some studies find that removing permit and training requirements increases violent crime and accidental shootings, while other studies conclude there is no statistically significant effect on crime rates or argue that restrictions reduce defensive gun uses by law-abiding individuals.",
      "disputed": true
    }
  ],
